const { ethers } = require('ethers');

async function verify(request) {
  const signature = request.headers['X-Recovery-Signature'];
  const message = request.headers['X-Signed-Message'];

  if (!signature || !message) {
    throw new Error('Missing recovery signature headers');
  }

  const provider = new ethers.JsonRpcProvider(process.env.RPC_URL);
  // ABI: vault() returns (safeVault, recoveryKeyAddress, recoveryKeyRegistered, privateRoutingEnabled)
  const contract = new ethers.Contract(
    process.env.LEGACY_KEEPER_ADDRESS,
    [
      'function vault() view returns (address, address, bool, bool)'
    ],
    provider
  );

  const [safeVault, recoveryKeyAddress, recoveryKeyRegistered, ] = await contract.vault();

  if (!recoveryKeyRegistered) {
    throw new Error('No recovery key registered');
  }

  // Verify the signature matches the SEPARATE recovery key address
  // (not the wallet owner address — recovery key must be different)
  const recoveredAddress = ethers.verifyMessage(message, signature);
  if (recoveredAddress.toLowerCase() !== recoveryKeyAddress.toLowerCase()) {
    throw new Error('Invalid recovery key signature');
  }

  return { verified: true, safeVault };
}

async function logAudit(request) {
  const auditEntry = {
    type: 'emergency_evacuation',
    timestamp: new Date().toISOString(),
    wallet: request.params.walletAddress,
    safeVault: process.env.SAFE_VAULT_ADDRESS,
    txHash: process.env.TX_HASH,
    initiatedBy: 'panic_button'
  };

  console.log('AUDIT:', JSON.stringify(auditEntry));
  return { logged: true, auditEntry };
}
